      "level": 10,
      "parent": "G11B20/0021",
      "ja": "",
      "en": "{characterised by a specific kind of data which is encrypted and recorded on and/or reproduced from the record carrier}",
      "count": 7,
      "ipcCode": "G11B20/00",
      "coreCode": "G11B20/00",
      "note": "",
      "sourceFile": "cpc_G11B.txt",
